#!/usr/bin/env python3
"""Build or check the gallery snapshot using the destination-aware installer."""
import argparse
import json
from pathlib import Path
import sys

import install

GENERATED = tuple(f'mods/one-piece/herdr-{name}.js' for name in
                  ('agents', 'spaces', 'menu', 'tabs', 'pane', 'chrome')) + (str(install.LAYOUT),)
NOTICE = ('Generated by tools/gallery.py through tools/install.py and tools/compat.py. '
          'Derived from Herdr, modified for Grand Fleet; Apache-2.0, '
          'see mods/one-piece/HERDR-LICENSE. Do not edit by hand.')


def package_files(repo, home):
    files = install.source_files(repo, home)
    result = {name: ('// ' + NOTICE + '\n').encode() + files[name] for name in GENERATED[:-1]}
    layout = json.loads(files[str(install.LAYOUT)])
    result[str(install.LAYOUT)] = install.encode_json({'$comment': NOTICE, **layout})
    return result


def apply(action, repo, home):
    files = package_files(repo, home)
    if action == 'check':
        changed = [name for name, content in files.items()
                   if not (repo / name).is_file() or (repo / name).read_bytes() != content]
        if changed:
            raise ValueError('Gallery snapshot differs from this destination: ' + ', '.join(changed)
                             + '. Use tools/install.py instead; do not copy the gallery snapshot.')
    else:
        for name, content in files.items():
            path = repo / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(content)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=('build', 'check'))
    parser.add_argument('--app-home', type=Path, required=True,
                        help='initialized Herdr source home (read only)')
    args = parser.parse_args()
    try:
        apply(args.action, Path(__file__).resolve().parents[1], args.app_home.expanduser().resolve())
    except (OSError, ValueError) as error:
        print(f'Gallery {args.action} failed: {error}', file=sys.stderr)
        return 1
    print(f'Gallery {args.action} passed')
    return 0


if __name__ == '__main__':
    sys.exit(main())
